package com.example.leetcodetrainer.curriculum.service;
import com.example.leetcodetrainer.curriculum.domain.*; import com.example.leetcodetrainer.curriculum.repository.*; import java.util.*; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional;
@Service @Transactional(readOnly=true) public class CurriculumFoundationService { private final SkillDefinitionRepository skills; private final ModeSkillRequirementRepository requirements; private final CurriculumItemRepository items; private final ProblemExposureRepository exposures; private final LearningSessionRepository sessions; public CurriculumFoundationService(SkillDefinitionRepository a,ModeSkillRequirementRepository b,CurriculumItemRepository c,ProblemExposureRepository d,LearningSessionRepository e){skills=a;requirements=b;items=c;exposures=d;sessions=e;} public List<SkillDefinition> skills(){return skills.findByActiveTrueOrderByDisplayOrderAsc();} public List<ModeSkillRequirement> requirements(){return requirements.findAllByOrderByLearningModeAscDisplayOrderAsc();} public List<CurriculumItem> items(){return items.findByActiveTrueOrderByDisplayOrderAsc();} public List<ProblemExposure> exposures(){return exposures.findAllByOrderByUpdatedAtDesc();} public List<LearningSession> sessions(){return sessions.findAllByOrderByCreatedAtDesc();} }
